From d37befacce19c6db59a4f0b2b577e11ce90d7df6 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 21:07:58 +0100
Subject: [PATCH] platformtheme: tell the global menu when a menu shortcut is
 used

Global menus had no way of knowing that an action from the application's
menus was triggered by its keyboard shortcut. When that happens, send a
D-Bus signal with the ids of the item and of the submenus that hold it.

BUG: 481368
---
 qt6/src/platformtheme/kdeplatformtheme.cpp | 62 +++++++++++++++++++++-
 1 file changed, 61 insertions(+), 1 deletion(-)

diff --git a/qt6/src/platformtheme/kdeplatformtheme.cpp b/qt6/src/platformtheme/kdeplatformtheme.cpp
index b630d22..e2d69fa 100644
--- a/qt6/src/platformtheme/kdeplatformtheme.cpp
+++ b/qt6/src/platformtheme/kdeplatformtheme.cpp
@@ -23,10 +23,13 @@
 #include <QApplication>
 #include <QDBusConnection>
 #include <QDBusConnectionInterface>
+#include <QDBusMessage>
 #include <QDebug>
 #include <QFont>
 #include <QLibraryInfo>
+#include <QMenu>
 #include <QPalette>
+#include <QShortcutEvent>
 #include <QString>
 #include <QStyle>
 #include <QVariant>
@@ -43,11 +46,62 @@
 #include <kstandardshortcut.h>

 #include "qxdgdesktopportalfiledialog_p.h"
+#include <private/qdbusplatformmenu_p.h>

 #include <KCountryFlagEmojiIconEngine>

 using namespace Qt::StringLiterals;

+namespace
+{
+// Tells the global menu which exported menu items an action triggered by its shortcut belongs to, so it can flash the menu
+class MenuShortcutNotifier : public QObject
+{
+public:
+    using QObject::QObject;
+
+    bool eventFilter(QObject *watched, QEvent *event) override
+    {
+        if (event->type() == QEvent::Shortcut && !static_cast<QShortcutEvent *>(event)->isAmbiguous()) {
+            if (auto action = qobject_cast<QAction *>(watched)) {
+                notify(action);
+            }
+        }
+        return false;
+    }
+
+private:
+    static void notify(QAction *action)
+    {
+        // The ids of the triggered item and of the submenu items leading to it
+        QList<int> ids;
+        while (action) {
+            QAction *parentAction = nullptr;
+            const auto objects = action->associatedObjects();
+            for (QObject *object : objects) {
+                auto menu = qobject_cast<QMenu *>(object);
+                QPlatformMenu *platformMenu = menu ? menu->platformMenu() : nullptr;
+                if (!platformMenu || qstrcmp(platformMenu->metaObject()->className(), "QDBusPlatformMenu") != 0) {
+                    continue;
+                }
+                if (auto item = static_cast<QDBusPlatformMenuItem *>(platformMenu->menuItemForTag(reinterpret_cast<quintptr>(action)))) {
+                    ids.append(item->dbusID());
+                    parentAction = menu->menuAction();
+                    break;
+                }
+            }
+            action = parentAction;
+        }
+        if (ids.isEmpty()) {
+            return;
+        }
+        QDBusMessage message = QDBusMessage::createSignal(u"/MenuBar"_s, u"org.kde.MenuBar"_s, u"ShortcutActivated"_s);
+        message << QVariant::fromValue(ids);
+        QDBusConnection::sessionBus().send(message);
+    }
+};
+}
+
 KdePlatformTheme::KdePlatformTheme()
 {
     loadSettings();
@@ -362,7 +416,13 @@ QPlatformMenuBar *KdePlatformTheme::createPlatformMenuBar() const
     if (qEnvironmentVariableIsSet("KDE_NO_GLOBAL_MENU")) {
         return nullptr;
     }
-    return QGenericUnixTheme::createPlatformMenuBar();
+    QPlatformMenuBar *menuBar = QGenericUnixTheme::createPlatformMenuBar();
+    static bool shortcutNotifierInstalled = false;
+    if (menuBar && !shortcutNotifierInstalled) {
+        qApp->installEventFilter(new MenuShortcutNotifier(qApp));
+        shortcutNotifierInstalled = true;
+    }
+    return menuBar;
 }

 // Force QtQuickControls to use org.kde.desktop theme for QApplication,
-- 
2.53.0

From c1f80407bfd3f2ab23f0a2f3398f5093b3771eb6 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 21:07:59 +0100
Subject: [PATCH] applets/appmenu: flash the menu of an item triggered by its
 shortcut

Using a keyboard shortcut gave no hint in the Global Menu of where that
action lives. Now, when the application reports that a menu item was
triggered by its shortcut, the menu holding it is briefly shown pressed.

BUG: 481368
---
 applets/appmenu/appmenumodel.cpp | 41 ++++++++++++++++++++++++++++++++
 applets/appmenu/appmenumodel.h   |  2 ++
 applets/appmenu/qml/main.qml     | 21 +++++++++++++++-
 3 files changed, 63 insertions(+), 1 deletion(-)

diff --git a/applets/appmenu/appmenumodel.cpp b/applets/appmenu/appmenumodel.cpp
index e91d858062..a67320b82d 100644
--- a/applets/appmenu/appmenumodel.cpp
+++ b/applets/appmenu/appmenumodel.cpp
@@ -302,6 +302,15 @@ void AppMenuModel::updateApplicationMenu(const QString &serviceName, const QStri
         return;
     }

+    if (!m_serviceName.isEmpty()) {
+        QDBusConnection::sessionBus().disconnect(m_serviceName,
+                                                 QStringLiteral("/MenuBar"),
+                                                 QStringLiteral("org.kde.MenuBar"),
+                                                 QStringLiteral("ShortcutActivated"),
+                                                 this,
+                                                 SLOT(onShortcutActivated(QList<int>)));
+    }
+
     if (serviceName.isEmpty() || menuObjectPath.isEmpty()) {
         setMenuAvailable(false);
         setVisible(false);
@@ -316,6 +325,12 @@ void AppMenuModel::updateApplicationMenu(const QString &serviceName, const QStri
         m_serviceWatcher->setWatchedServices(QStringList({m_serviceName}));

         m_importer = std::make_unique<KDBusMenuImporter>(serviceName, menuObjectPath);
+        QDBusConnection::sessionBus().connect(m_serviceName,
+                                              QStringLiteral("/MenuBar"),
+                                              QStringLiteral("org.kde.MenuBar"),
+                                              QStringLiteral("ShortcutActivated"),
+                                              this,
+                                              SLOT(onShortcutActivated(QList<int>)));
         QMetaObject::invokeMethod(m_importer.get(), "updateMenu", Qt::QueuedConnection);

         connect(m_importer.get(), &DBusMenuImporter::menuUpdated, this, [=, this](QMenu *menu) {
@@ -379,4 +394,30 @@ void AppMenuModel::updateApplicationMenu(const QString &serviceName, const QStri
     }
 }

+void AppMenuModel::onShortcutActivated(const QList<int> &ids)
+{
+    if (!m_menuAvailable || !m_menu || !m_importer) {
+        return;
+    }
+
+    // Flash the top-level menu that holds the first of these items we know about
+    const auto actions = m_menu->actions();
+    for (int id : ids) {
+        QAction *action = m_importer->actionForId(id);
+        if (!action) {
+            continue;
+        }
+        const auto objects = action->associatedObjects();
+        for (QObject *object : objects) {
+            auto it = std::ranges::find_if(actions, [object](QAction *topLevelAction) {
+                return topLevelAction->menu() && topLevelAction->menu() == object;
+            });
+            if (it != actions.end()) {
+                Q_EMIT shortcutActivated(it - actions.begin());
+                return;
+            }
+        }
+    }
+}
+
 #include "moc_appmenumodel.cpp"
diff --git a/applets/appmenu/appmenumodel.h b/applets/appmenu/appmenumodel.h
index ba4a64eaa1..b7fc85feee 100644
--- a/applets/appmenu/appmenumodel.h
+++ b/applets/appmenu/appmenumodel.h
@@ -68,11 +68,13 @@ public:
 Q_SIGNALS:
     void requestActivateIndex(int index);
     void bringToFocus(int index);
+    void shortcutActivated(int index);

 private Q_SLOTS:
     void onActiveWindowChanged();
     void setVisible(bool visible);
     void update();
+    void onShortcutActivated(const QList<int> &ids);

 Q_SIGNALS:
     void allScreensChanged();
diff --git a/applets/appmenu/qml/main.qml b/applets/appmenu/qml/main.qml
index e9f5280a3f..e2d278477d 100644
--- a/applets/appmenu/qml/main.qml
+++ b/applets/appmenu/qml/main.qml
@@ -72,6 +72,25 @@ PlasmoidItem {
         rowSpacing: 0
         columnSpacing: 0

+        // Menu briefly shown as pressed after one of its items was triggered by its shortcut
+        property int flashedIndex: -1
+
+        Timer {
+            id: flashTimer
+            interval: Kirigami.Units.longDuration
+            onTriggered: buttonGrid.flashedIndex = -1
+        }
+
+        Connections {
+            target: appMenuModel
+            function onShortcutActivated(index: int) {
+                if (Plasmoid.currentIndex === -1) {
+                    buttonGrid.flashedIndex = index;
+                    flashTimer.restart();
+                }
+            }
+        }
+
         Binding {
             target: Plasmoid
             property: "buttonGrid"
@@ -122,7 +141,7 @@ PlasmoidItem {
                 text: activeMenu
                 Kirigami.MnemonicData.active: altState.pressed

-                down: Plasmoid.currentIndex === index
+                down: Plasmoid.currentIndex === index || buttonGrid.flashedIndex === index
                 visible: text !== "" && (activeActions?.visible ?? false)

                 menuIsOpen: Plasmoid.currentIndex !== -1
-- 
2.53.0
